package com.turboio.addon;
import android.content.*;import android.security.keystore.*;import android.util.Base64;
import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;

/** Separate authenticated Keystore envelope; no task/official credentials mixed. */
final class MaterialSettings {
 private static final Object LOCK=new Object();private static final String ALIAS="io.agent.materials.config.v1";
 private static final byte[] AAD="io-agent/material-connection/1".getBytes(StandardCharsets.UTF_8);private final SharedPreferences prefs;
 MaterialSettings(Context app){prefs=app.getSharedPreferences("io_agent_materials_v1",Context.MODE_PRIVATE);}
 private static SecretKey key(boolean create)throws Exception{KeyStore store=KeyStore.getInstance("AndroidKeyStore");store.load(null);if(store.containsAlias(ALIAS))return (SecretKey)store.getKey(ALIAS,null);if(!create)throw new IllegalStateException("MATERIAL_KEY_UNAVAILABLE");KeyGenerator gen=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");gen.init(new KeyGenParameterSpec.Builder(ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setRandomizedEncryptionRequired(true).build());return gen.generateKey();}
 MaterialConfig load()throws Exception{synchronized(LOCK){String text=prefs.getString("sealed",null);if(text==null)return null;MaterialWire.require(text.length()<=17000,"MATERIAL_CONFIG_INVALID");byte[] data=Base64.decode(text,Base64.NO_WRAP);MaterialWire.require(data.length>=29&&data.length<=12316,"MATERIAL_CONFIG_INVALID");Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(false),new GCMParameterSpec(128,Arrays.copyOf(data,12)));cipher.updateAAD(AAD);byte[] plain=cipher.doFinal(Arrays.copyOfRange(data,12,data.length));try{return MaterialConfig.decode(plain);}finally{Arrays.fill(plain,(byte)0);}}}
 void save(MaterialConfig config)throws Exception{synchronized(LOCK){MaterialConfig old=load();if(old!=null)old.replaceAllowed(config);byte[] plain=config.encode();try{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key(true));cipher.updateAAD(AAD);byte[] encrypted=cipher.doFinal(plain),iv=cipher.getIV();MaterialWire.require(iv.length==12,"MATERIAL_CONFIG_INVALID");byte[] sealed=new byte[12+encrypted.length];System.arraycopy(iv,0,sealed,0,12);System.arraycopy(encrypted,0,sealed,12,encrypted.length);if(!prefs.edit().putString("sealed",Base64.encodeToString(sealed,Base64.NO_WRAP)).commit())throw new IllegalStateException("MATERIAL_CONFIG_SAVE_FAILED");if(!Arrays.equals(load().encode(),plain))throw new IllegalStateException("MATERIAL_CONFIG_SAVE_FAILED");}finally{Arrays.fill(plain,(byte)0);}}}
}
